import{LOWER_SHRUB as R}from'./lower-shrub-registration.mjs';
const moduleURL=import.meta.url;const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
export async function loadLowerShrubLayer({fetcher=fetch,decode=async b=>createImageBitmap(new Blob([b])),signal,canvasFactory}={}){let image=null,tile=null,disposed=false;const check=()=>{if(signal?.aborted)throw Error('LOWER_SHRUB_CANCELLED')},dispose=()=>{if(disposed)return;disposed=true;image?.close?.();if(tile){tile.width=0;tile.height=0}};try{check();const response=await fetcher(new URL('./assets/forest-lower-shrub-r1.png',moduleURL),{signal});if(!response.ok)throw Error('LOWER_SHRUB_MISSING');const raw=await response.arrayBuffer(),bytes=new Uint8Array(raw instanceof ArrayBuffer?raw.slice(0):raw);check();if(await hash(bytes)!==R.patchSHA)throw Error('LOWER_SHRUB_PIN_MISMATCH');check();image=await decode(bytes);check();if(image.width!==R.width||image.height!==R.height)throw Error('LOWER_SHRUB_DIMENSIONS');const[x,y,x1,y1]=R.roiHalfOpen,w=x1-x,h=y1-y;tile=canvasFactory(w,h);const ctx=tile.getContext('2d');ctx.drawImage(image,R.referenceWorldRect[0]-x,R.referenceWorldRect[1]-y,R.referenceWorldRect[2],R.referenceWorldRect[3]);const p=ctx.getImageData(0,0,w,h),[bx,by]=R.protectedBuilding;for(let yy=0;yy<h;yy++)for(let xx=0;xx<w;xx++){const feather=Math.min(1,(xx+1)/R.feather,(yy+1)/R.feather,(w-xx)/R.feather,(h-yy)/R.feather,Math.max(0,Math.max(bx-(x+xx),by-(y+yy)))/R.feather);p.data[(yy*w+xx)*4+3]=Math.round(p.data[(yy*w+xx)*4+3]*feather)}ctx.putImageData(p,0,0);return Object.freeze({registration:R,draw(ctx,{offsetX=0,offsetY=0}={}){if(!disposed)ctx.drawImage(tile,x-offsetX,y-offsetY)},dispose})}catch(e){dispose();throw e}}
